package proxy

import (
	"bufio"
	"context"
	"fmt"
	"io"
	"net"
	"net/http"
	"strconv"
	"strings"
	"sync"
)

// FeatureFlags controls SDK behavior for cloud infrastructure routing
type FeatureFlags struct {
	mu              sync.RWMutex
	EnableChunked   bool
	EnableKeepAlive bool
	StrictParsing   bool
	MaxBodySize     int64
}

var DefaultFlags = &FeatureFlags{
	EnableChunked:   true,
	EnableKeepAlive: true,
	StrictParsing:   true,
	MaxBodySize:     10 << 20, // 10MB
}

// TransportLayer handles HTTP forwarding between SDK client and backend services
type TransportLayer struct {
	flags    *FeatureFlags
	backend  string
	dialer   net.Dialer
}

func NewTransportLayer(backend string, flags *FeatureFlags) *TransportLayer {
	return &TransportLayer{
		flags:   flags,
		backend: backend,
	}
}

// normalizeTransferEncoding processes the Transfer-Encoding header
// according to RFC 7230 Section 3.3.1 rules
func (t *TransportLayer) normalizeTransferEncoding(headers http.Header) string {
	te := headers.Get("Transfer-Encoding")
	if te == "" {
		return ""
	}
	// Parse comma-separated encodings
	encodings := strings.Split(strings.ToLower(te), ",")
	var normalized []string
	for _, enc := range encodings {
		enc = strings.TrimSpace(enc)
		if enc == "chunked" || enc == "identity" {
			normalized = append(normalized, enc)
		}
	}
	return strings.Join(normalized, ", ")
}

// resolveContentLength determines the effective body length
// Priority: Transfer-Encoding > Content-Length per RFC 7230 3.3.3
func (t *TransportLayer) resolveContentLength(req *http.Request) int64 {
	t.flags.mu.RLock()
	chunkedEnabled := t.flags.EnableChunked
	t.flags.mu.RUnlock()

	te := t.normalizeTransferEncoding(req.Header)
	cl := req.Header.Get("Content-Length")

	// RFC 7230 3.3.3: If Transfer-Encoding is present, Content-Length MUST be ignored
	// This is enforced regardless of feature flag state to prevent smuggling
	if te != "" && cl != "" {
		// Always prioritize Transfer-Encoding when both are present
		if chunkedEnabled {
			return -1
		}
		// If chunked is disabled, reject ambiguous requests
		return 0
	}

	if te != "" && chunkedEnabled {
		return -1
	}

	if cl != "" {
		len, err := strconv.ParseInt(cl, 10, 64)
		if err != nil || len < 0 {
			return 0
		}
		return len
	}

	return 0
}

// containsCTL reports whether s contains any control characters that could
// be used for header/request injection (CR, LF, NUL, etc.).
func containsCTL(s string) bool {
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < 0x20 || c == 0x7f {
			return true
		}
	}
	return false
}

// ForwardRequest proxies an inbound request to the backend service
func (t *TransportLayer) ForwardRequest(ctx context.Context, inbound *http.Request) (*http.Response, error) {
	conn, err := t.dialer.DialContext(ctx, "tcp", t.backend)
	if err != nil {
		return nil, fmt.Errorf("backend dial failed: %w", err)
	}

	bodyLen := t.resolveContentLength(inbound)

	// Determine the configured maximum body size for enforcement.
	t.flags.mu.RLock()
	maxBodySize := t.flags.MaxBodySize
	t.flags.mu.RUnlock()

	// Enforce the maximum body size for declared Content-Length bodies.
	if maxBodySize > 0 && bodyLen > maxBodySize {
		conn.Close()
		return nil, fmt.Errorf("request body exceeds maximum allowed size (%d bytes)", maxBodySize)
	}

	// Build the forwarded request line
	var reqBuf strings.Builder
	reqBuf.WriteString(fmt.Sprintf("%s %s HTTP/1.1\r\n", inbound.Method, inbound.URL.RequestURI()))
	reqBuf.WriteString(fmt.Sprintf("Host: %s\r\n", t.backend))

	// Forward headers, applying normalization
	for key, vals := range inbound.Header {
		lowerKey := strings.ToLower(key)
		if lowerKey == "transfer-encoding" || lowerKey == "content-length" {
			continue // We'll set these ourselves
		}
		// Reject header names containing control characters to prevent injection.
		if containsCTL(key) {
			continue
		}
		for _, v := range vals {
			// Reject header values containing CR/LF or other control chars
			// to prevent CRLF/header/request injection.
			if containsCTL(v) {
				continue
			}
			reqBuf.WriteString(fmt.Sprintf("%s: %s\r\n", key, v))
		}
	}

	// Set the appropriate body framing header
	if bodyLen == -1 {
		reqBuf.WriteString("Transfer-Encoding: chunked\r\n")
	} else if bodyLen > 0 {
		reqBuf.WriteString(fmt.Sprintf("Content-Length: %d\r\n", bodyLen))
	}

	reqBuf.WriteString("\r\n")

	// Write headers
	_, err = io.WriteString(conn, reqBuf.String())
	if err != nil {
		conn.Close()
		return nil, err
	}

	// Write body
	if bodyLen == -1 {
		// Chunked transfer
		writer := newChunkedWriter(conn)
		var src io.Reader = inbound.Body
		if maxBodySize > 0 {
			// Cap the amount of data forwarded to prevent unbounded
			// resource consumption. Read one extra byte to detect overflow.
			limited := io.LimitReader(inbound.Body, maxBodySize+1)
			var copied int64
			copied, err = io.Copy(writer, limited)
			if err == nil && copied > maxBodySize {
				err = fmt.Errorf("request body exceeds maximum allowed size (%d bytes)", maxBodySize)
			}
			_ = src
		} else {
			_, err = io.Copy(writer, inbound.Body)
		}
		writer.Close()
	} else if bodyLen > 0 {
		_, err = io.CopyN(conn, inbound.Body, bodyLen)
	}

	if err != nil {
		conn.Close()
		return nil, err
	}

	// Read response
	resp, err := http.ReadResponse(bufio.NewReader(conn), inbound)
	if err != nil {
		conn.Close()
		return nil, err
	}

	return resp, nil
}

type chunkedWriter struct {
	w io.WriteCloser
}

func newChunkedWriter(w io.WriteCloser) *chunkedWriter {
	return &chunkedWriter{w: w}
}

func (cw *chunkedWriter) Write(p []byte) (int, error) {
	if len(p) == 0 {
		return 0, nil
	}
	_, err := fmt.Fprintf(cw.w, "%x\r\n", len(p))
	if err != nil {
		return 0, err
	}
	n, err := cw.w.Write(p)
	if err != nil {
		return n, err
	}
	_, err = fmt.Fprintf(cw.w, "\r\n")
	return n, err
}

func (cw *chunkedWriter) Close() error {
	_, err := fmt.Fprintf(cw.w, "0\r\n\r\n")
	return err
}
